package com.limpyo.app.core.data

import com.limpyo.app.core.model.Barangay
import com.limpyo.app.core.model.GeoPoint
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import kotlin.math.cos
import kotlin.math.sqrt

/** Reads app/src/main/assets/barangays.json (generated by supabase/seed/build-app-barangays.mjs). */
object BarangayParser {
    @Serializable
    private data class FileDto(val version: Int, val barangays: List<BarangayDto>)

    @Serializable
    private data class BarangayDto(
        val id: Int,
        val name: String,
        val center: List<Double>,
        val approximate: Boolean,
        val polygons: List<List<List<List<Double>>>>,
    )

    private val json = Json { ignoreUnknownKeys = true }

    fun parse(text: String): List<Barangay> =
        json.decodeFromString<FileDto>(text).barangays
            .map { b ->
                Barangay(
                    id = b.id,
                    name = b.name,
                    center = GeoPoint(lat = b.center[1], lon = b.center[0]),
                    approximate = b.approximate,
                    polygons = b.polygons.map { poly -> poly.map { ring -> ring.map { GeoPoint(lat = it[1], lon = it[0]) } } },
                )
            }
            .sortedBy { it.id }
}

/**
 * "Which barangay is this point in?" done on the phone, so a location never leaves the device.
 * Uses the even-odd (ray casting) rule; the areas are small enough that flat lat/lon math is fine.
 */
class BarangayLocator(private val barangays: List<Barangay>) {

    fun find(point: GeoPoint): Barangay? =
        barangays.firstOrNull { b -> b.polygons.any { poly -> inPolygon(point, poly) } }
            ?: nearestWithin(point, FALLBACK_METERS)

    /** Points on the coast or just past the approximate outline still get the closest barangay. */
    private fun nearestWithin(point: GeoPoint, meters: Double): Barangay? =
        barangays
            .map { it to distanceMeters(point, it.center) }
            .filter { it.second <= meters }
            .minByOrNull { it.second }
            ?.first

    private fun inPolygon(p: GeoPoint, rings: List<List<GeoPoint>>): Boolean {
        if (rings.isEmpty() || !inRing(p, rings[0])) return false
        return rings.drop(1).none { hole -> inRing(p, hole) }
    }

    private fun inRing(p: GeoPoint, ring: List<GeoPoint>): Boolean {
        var inside = false
        var j = ring.lastIndex
        for (i in ring.indices) {
            val a = ring[i]
            val b = ring[j]
            if ((a.lat > p.lat) != (b.lat > p.lat) &&
                p.lon < (b.lon - a.lon) * (p.lat - a.lat) / (b.lat - a.lat) + a.lon
            ) {
                inside = !inside
            }
            j = i
        }
        return inside
    }

    private fun distanceMeters(a: GeoPoint, b: GeoPoint): Double {
        val metersPerDegLat = 111_320.0
        val dy = (a.lat - b.lat) * metersPerDegLat
        val dx = (a.lon - b.lon) * metersPerDegLat * cos(Math.toRadians((a.lat + b.lat) / 2))
        return sqrt(dx * dx + dy * dy)
    }

    private companion object {
        const val FALLBACK_METERS = 3_000.0
    }
}
